import styles from './Screenshot.module.css';

export function Screenshot({ src, alt }) {
  const image = {
    src,
    alt,
  };

  return (
    <div className={styles.screenshotContainer}>
      <img src={image.src} alt={image.alt} className={styles.image} />
    </div>
  );
}
